),(186296,4523,31),(186297,4523,33),(186298,4523,34),(186299,4523,35),(186300,4523,139),(186301,4524,1),(186302,4524,2),(186303,4524,3),(186304,4524,143),(186305,4524,4),(186306,4524,5),(186307,4524,6),(186308,4524,133),(186309,4524,40),(186310,4524,41),(186311,4524,97),(186312,4524,43),(186313,4524,89),(186314,4524,8),(186315,4524,44),(186316,4524,9),(186317,4524,46),(186318,4524,47),(186319,4524,48),(186320,4524,10),(186321,4524,12),(186322,4524,90),(186323,4524,51),(186324,4524,52),(186325,4524,161),(186326,4524,53),(186327,4524,104),(186328,4524,56),(186329,4524,105),(186330,4524,17),(186331,4524,59),(186332,4524,18),(186333,4524,19),(186334,4524,20),(186335,4524,21),(186336,4524,22),(186337,4524,63),(186338,4524,65),(186339,4524,135),(186340,4524,109),(186341,4524,172),(186342,4524,110),(186343,4524,79),(186344,4524,24),(186345,4524,25),(186346,4524,112),(186347,4524,26),(186348,4524,156),(186349,4524,27),(186350,4524,28),(186351,4524,66),(186352,4524,30),(186353,4524,31),(186354,4524,32),(186355,4524,33),(186356,4524,34),(186357,4524,35),(186358,4524,139);
