DROP TABLE IF EXISTS `listings`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `listings` (
  `id` int NOT NULL AUTO_INCREMENT,
  `listingUrl` text CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  `name` text CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  `description` text CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  `neighborhoodOverview` text CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  `pictureUrl` text CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  `hostId` int NOT NULL,
  `neighborhoodId` int NOT NULL,
  `latitude` text CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci NOT NULL,
  `longitude` text CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci NOT NULL,
  `roomTypeId` int NOT NULL,
  `accommodates` int DEFAULT NULL,
  `bathrooms` decimal(13,2) DEFAULT NULL,
  `bedrooms` decimal(13,2) DEFAULT NULL,
  `beds` decimal(13,2) DEFAULT NULL,
  `price` decimal(13,2) NOT NULL,
  `minNights` int DEFAULT NULL,
  `maxNights` int DEFAULT NULL,
  `numReviews` int DEFAULT NULL,
  `rating` decimal(13,2) DEFAULT NULL,
  `extId` bigint NOT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=4525 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
/*!40101 SET character_set_client = @saved_cs_client */;

